 	"testing"

 	"github.com/KogenAI/kogen-executor/core"
@@ -99,3 +100,114 @@ func TestReportVerificationErrorRetainsSubmittedEvidence(t *testing.T) {
 		t.Fatalf("report: %+v code %d", out, code)
 	}
 }
+
+// invalidInputFixture is a committed checkout with an Intent, its acceptance feature and no
+// project configuration; the returned values are its root and its start commit.
+func invalidInputFixture(t *testing.T) (root, start string) {
+	t.Helper()
+	root = t.TempDir()
+	git := func(args ...string) string {
+		t.Helper()
+		c := exec.Command("git", args...)
+		c.Dir = root
+		b, e := c.CombinedOutput()
+		if e != nil {
+			t.Fatalf("git %v: %v %s", args, e, b)
+		}
+		return string(bytes.TrimSpace(b))
+	}
+	for name, text := range map[string]string{
+		".kogen/intents/tiny/intent.md":          "# Tiny\n\nSlug: tiny\nModel: not applicable — simple\nAcceptance:\n- .kogen/intents/tiny/acceptance.feature\n",
+		".kogen/intents/tiny/acceptance.feature": "Feature: Tiny\n",
+		"README.md":                              "tiny\n",
+	} {
+		p := filepath.Join(root, name)
+		if e := os.MkdirAll(filepath.Dir(p), 0755); e != nil {
+			t.Fatal(e)
+		}
+		if e := os.WriteFile(p, []byte(text), 0644); e != nil {
+			t.Fatal(e)
+		}
+	}
+	git("init", "-q")
+	git("add", "-A")
+	git("commit", "-qm", "start")
+	return root, git("rev-parse", "HEAD")
+}
+
+// runRefused runs the command on args and requires exit 2, nothing on stdout and no run folder
+// (TMPDIR is a folder of the test, so a run folder would show in it). It returns stderr.
+func runRefused(t *testing.T, args []string) string {
+	t.Helper()
+	tmp := t.TempDir()
+	t.Setenv("TMPDIR", tmp)
+	var out, stderr bytes.Buffer
+	code := run(args, &out, &stderr)
+	if code != 2 {
+		t.Errorf("exit code %d, want 2; stdout %q, stderr %q", code, out.String(), stderr.String())
+	}
+	if out.Len() != 0 {
+		t.Errorf("stdout %q, want empty", out.String())
+	}
+	if left, e := os.ReadDir(tmp); e != nil || len(left) != 0 {
+		t.Errorf("review work started: %v %v", left, e)
+	}
+	return stderr.String()
+}
+
+func TestUsageErrorsAreRefused(t *testing.T) {
+	missing := filepath.Join(t.TempDir(), "absent")
+	for _, tc := range []struct {
+		name string
+		args []string
+	}{
+		{"no arguments", nil},
+		{"missing start", []string{"-root", missing, "-slug", "tiny", "-model", "test"}},
+		{"missing slug", []string{"-root", missing, "-start", "HEAD", "-model", "test"}},
+		{"missing model", []string{"-root", missing, "-start", "HEAD", "-slug", "tiny"}},
+		{"positional argument", []string{"-root", missing, "-start", "HEAD", "-slug", "tiny", "-model", "test", "extra"}},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			if stderr := runRefused(t, tc.args); !strings.Contains(stderr, usage) {
+				t.Errorf("stderr %q does not print the usage line", stderr)
+			}
+		})
+	}
+}
+
+func TestUnusableCheckoutIsRefused(t *testing.T) {
+	for _, tc := range []struct {
+		name, want string
+		change     func(t *testing.T, root string, args []string) []string
+	}{
+		{"missing intent", "intent.md", func(t *testing.T, root string, args []string) []string {
+			return append(args, "-slug", "absent")
+		}},
+		{"missing acceptance feature", "acceptance.feature", func(t *testing.T, root string, args []string) []string {
+			if e := os.Remove(filepath.Join(root, ".kogen/intents/tiny/acceptance.feature")); e != nil {
+				t.Fatal(e)
+			}
+			return args
+		}},
+		{"invalid project configuration", "project_config_invalid", func(t *testing.T, root string, args []string) []string {
+			if e := os.WriteFile(filepath.Join(root, ".kogen/project.yaml"), []byte("version: seven\n"), 0644); e != nil {
+				t.Fatal(e)
+			}
+			return args
+		}},
+		{"unresolvable start commit", "-start no-such-revision is not a commit of", func(t *testing.T, root string, args []string) []string {
+			args[3] = "no-such-revision"
+			return args
+		}},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			root, start := invalidInputFixture(t)
+			args := []string{"-root", root, "-start", start, "-model", "test", "-provider", "openai-compatible", "-base-url", "http://127.0.0.1:1/v1", "-slug", "tiny"}
+			args = tc.change(t, root, args)
+			stderr := runRefused(t, args)
+			if !strings.HasPrefix(stderr, "kogen-review: ") || !strings.Contains(stderr, tc.want) {
+				t.Errorf("stderr %q is not a kogen-review refusal naming %q", stderr, tc.want)
+			}
+		})
+	}
+}

